/* TileLang TPU target: bm1690, programming model: tpukernel */
#include "ppl_helper.h"
#ifndef TILELANG_TPU_TPUKERNEL
#error "TPU-Kernel externs require -tpu-programming-model=tpukernel"
#endif
typedef struct {
    dim4 shape;
    dim4 stride;
    global_addr_t addr;
    bool default_stride;
} __tilelang_tpu_tensor_info;

void elementwise_sub(global_addr_t v1, global_addr_t v2, global_addr_t v3) {
  __tilelang_tpu_tensor_info v4 = {.shape = {1, 1024, 1, 1024} , .stride = {0}, .addr = v1, .default_stride = true};
  __tilelang_tpu_tensor_info v5 = {.shape = {1, 1024, 1, 1024} , .stride = {0}, .addr = v2, .default_stride = true};
  __tilelang_tpu_tensor_info v6 = {.shape = {1, 1024, 1, 1024} , .stride = {0}, .addr = v3, .default_stride = true};
  __tilelang_tpu_tensor_info lhs_local = {.shape = { 1, 1024, 1, 1024}, .stride = {0}, .addr = 0, .default_stride = false};
  tpu_aligned_stride(&lhs_local.stride, 0, &lhs_local.shape, DT_FP16);
  __tilelang_tpu_tensor_info rhs_local = {.shape = { 1, 1024, 1, 1024}, .stride = {0}, .addr = 32768, .default_stride = false};
  tpu_aligned_stride(&rhs_local.stride, 0, &rhs_local.shape, DT_FP16);
  __tilelang_tpu_tensor_info dst_local = {.shape = { 1, 1024, 1, 1024}, .stride = {0}, .addr = 65536, .default_stride = false};
  tpu_aligned_stride(&dst_local.stride, 0, &dst_local.shape, DT_FP16);
  __tilelang_tpu_tensor_info lhs = {.shape = {1, 1024, 1, 1024} , .stride = {1048576, 1024, 1024, 1} , .addr = v4.addr + ((0) * 1024+(0) * 1 ) * 2, .default_stride = false};
  __tilelang_tpu_tensor_info lhs_local_1 = {.shape = {1, 1024, 1, 1024} , .stride = lhs_local.stride, .addr = lhs_local.addr + ((0) * lhs_local.stride.c+(0) * lhs_local.stride.w ) * 2, .default_stride = lhs_local.default_stride};
  tpu_gdma_cpy_S2L(lhs_local_1.addr, lhs.addr, &lhs_local_1.shape, (lhs_local_1.default_stride ? NULL : &lhs_local_1.stride), (lhs.default_stride ? NULL : &lhs.stride), DT_FP16);
  __tilelang_tpu_tensor_info rhs = {.shape = {1, 1024, 1, 1024} , .stride = {1048576, 1024, 1024, 1} , .addr = v5.addr + ((0) * 1024+(0) * 1 ) * 2, .default_stride = false};
  __tilelang_tpu_tensor_info rhs_local_1 = {.shape = {1, 1024, 1, 1024} , .stride = rhs_local.stride, .addr = rhs_local.addr + ((0) * rhs_local.stride.c+(0) * rhs_local.stride.w ) * 2, .default_stride = rhs_local.default_stride};
  tpu_gdma_cpy_S2L(rhs_local_1.addr, rhs.addr, &rhs_local_1.shape, (rhs_local_1.default_stride ? NULL : &rhs_local_1.stride), (rhs.default_stride ? NULL : &rhs.stride), DT_FP16);
  tpu_bdc_fp_sub(dst_local.addr, lhs_local.addr, rhs_local.addr, &dst_local.shape, (dst_local.default_stride ? NULL : &dst_local.stride), (lhs_local.default_stride ? NULL : &lhs_local.stride), (rhs_local.default_stride ? NULL : &rhs_local.stride), DT_FP16);
  __tilelang_tpu_tensor_info dst_local_1 = {.shape = {1, 1024, 1, 1024} , .stride = dst_local.stride, .addr = dst_local.addr + ((0) * dst_local.stride.c+(0) * dst_local.stride.w ) * 2, .default_stride = dst_local.default_stride};
  __tilelang_tpu_tensor_info dst = {.shape = {1, 1024, 1, 1024} , .stride = {1048576, 1024, 1024, 1} , .addr = v6.addr + ((0) * 1024+(0) * 1 ) * 2, .default_stride = false};
  tpu_gdma_cpy_L2S(dst.addr, dst_local_1.addr, &dst.shape, (dst.default_stride ? NULL : &dst.stride), (dst_local_1.default_stride ? NULL : &dst_local_1.stride), DT_FP16);
}

typedef struct {
  global_addr_t v1;
  global_addr_t v2;
  global_addr_t v3;
} tpu_kernel_api_main_inner_args_t;
int main_kernel(const void * args) {
  tpu_kernel_api_main_inner_args_t *api = (tpu_kernel_api_main_inner_args_t*)args;
  tpu_initialize();
  elementwise_sub(api->v1,
    api->v2,
    api->v3);
  tpu_poll();
  return 0;
}
TPUKERNEL_FUNC_REGISTER(main_kernel)

