/* TileLang TPU target: bm1690, programming model: tpukernel */
#include "ppl_helper.h"
#ifndef TILELANG_TPU_TPUKERNEL
#error "TPU-Kernel externs require -tpu-programming-model=tpukernel"
#endif
typedef struct {
    dim4 shape;
    dim4 stride;
    global_addr_t addr;
    bool default_stride;
} __tilelang_tpu_tensor_info;

void elementwise_tiled(global_addr_t v1, global_addr_t v2, global_addr_t v3) {
  __tilelang_tpu_tensor_info v4 = {.shape = {1, 1024, 1, 1024} , .stride = {0}, .addr = v1, .default_stride = true};
  __tilelang_tpu_tensor_info v5 = {.shape = {1, 1024, 1, 1024} , .stride = {0}, .addr = v2, .default_stride = true};
  __tilelang_tpu_tensor_info v6 = {.shape = {1, 1024, 1, 1024} , .stride = {0}, .addr = v3, .default_stride = true};
  __tilelang_tpu_tensor_info a = {.shape = { 1, 128, 1, 1024}, .stride = {0}, .addr = 0, .default_stride = false};
  tpu_aligned_stride(&a.stride, 0, &a.shape, DT_FP16);
  __tilelang_tpu_tensor_info b = {.shape = { 1, 128, 1, 1024}, .stride = {0}, .addr = 16384, .default_stride = false};
  tpu_aligned_stride(&b.stride, 0, &b.shape, DT_FP16);
  __tilelang_tpu_tensor_info c = {.shape = { 1, 128, 1, 1024}, .stride = {0}, .addr = 8192, .default_stride = false};
  tpu_aligned_stride(&c.stride, 0, &c.shape, DT_FP16);
  __tilelang_tpu_tensor_info a_pipeline_v1 = {.shape = { 1, 128, 1, 1024}, .stride = {0}, .addr = 4096, .default_stride = false};
  tpu_aligned_stride(&a_pipeline_v1.stride, 0, &a_pipeline_v1.shape, DT_FP16);
  __tilelang_tpu_tensor_info b_pipeline_v1 = {.shape = { 1, 128, 1, 1024}, .stride = {0}, .addr = 20480, .default_stride = false};
  tpu_aligned_stride(&b_pipeline_v1.stride, 0, &b_pipeline_v1.shape, DT_FP16);
  __tilelang_tpu_tensor_info lhs = {.shape = {1, 128, 1, 1024} , .stride = {1048576, 1024, 1024, 1} , .addr = v4.addr + ((0) * 1024+(0) * 1 ) * 2, .default_stride = false};
  __tilelang_tpu_tensor_info a_1 = {.shape = {1, 128, 1, 1024} , .stride = a.stride, .addr = a.addr + ((0) * a.stride.c+(0) * a.stride.w ) * 2, .default_stride = a.default_stride};
  tpu_gdma_cpy_S2L(a_1.addr, lhs.addr, &a_1.shape, (a_1.default_stride ? NULL : &a_1.stride), (lhs.default_stride ? NULL : &lhs.stride), DT_FP16);
  __tilelang_tpu_tensor_info rhs = {.shape = {1, 128, 1, 1024} , .stride = {1048576, 1024, 1024, 1} , .addr = v5.addr + ((0) * 1024+(0) * 1 ) * 2, .default_stride = false};
  __tilelang_tpu_tensor_info b_1 = {.shape = {1, 128, 1, 1024} , .stride = b.stride, .addr = b.addr + ((0) * b.stride.c+(0) * b.stride.w ) * 2, .default_stride = b.default_stride};
  tpu_gdma_cpy_S2L(b_1.addr, rhs.addr, &b_1.shape, (b_1.default_stride ? NULL : &b_1.stride), (rhs.default_stride ? NULL : &rhs.stride), DT_FP16);
  for (int32_t tile_pipeline = 0; tile_pipeline < 7; ++tile_pipeline) {
    if ((tile_pipeline % 2) == 0) {
#ifndef USING_CMODEL
      tpu_parallel_start();
#endif
      __tilelang_tpu_tensor_info lhs_1 = {.shape = {1, 128, 1, 1024} , .stride = {1048576, 1024, 1024, 1} , .addr = v4.addr + ((((tile_pipeline * 128) + 128)) * 1024+(0) * 1 ) * 2, .default_stride = false};
      __tilelang_tpu_tensor_info a_pipeline_v1_1 = {.shape = {1, 128, 1, 1024} , .stride = a_pipeline_v1.stride, .addr = a_pipeline_v1.addr + ((0) * a_pipeline_v1.stride.c+(0) * a_pipeline_v1.stride.w ) * 2, .default_stride = a_pipeline_v1.default_stride};
      tpu_gdma_cpy_S2L(a_pipeline_v1_1.addr, lhs_1.addr, &a_pipeline_v1_1.shape, (a_pipeline_v1_1.default_stride ? NULL : &a_pipeline_v1_1.stride), (lhs_1.default_stride ? NULL : &lhs_1.stride), DT_FP16);
      __tilelang_tpu_tensor_info rhs_1 = {.shape = {1, 128, 1, 1024} , .stride = {1048576, 1024, 1024, 1} , .addr = v5.addr + ((((tile_pipeline * 128) + 128)) * 1024+(0) * 1 ) * 2, .default_stride = false};
      __tilelang_tpu_tensor_info b_pipeline_v1_1 = {.shape = {1, 128, 1, 1024} , .stride = b_pipeline_v1.stride, .addr = b_pipeline_v1.addr + ((0) * b_pipeline_v1.stride.c+(0) * b_pipeline_v1.stride.w ) * 2, .default_stride = b_pipeline_v1.default_stride};
      tpu_gdma_cpy_S2L(b_pipeline_v1_1.addr, rhs_1.addr, &b_pipeline_v1_1.shape, (b_pipeline_v1_1.default_stride ? NULL : &b_pipeline_v1_1.stride), (rhs_1.default_stride ? NULL : &rhs_1.stride), DT_FP16);
      tpu_bdc_fp_sub(c.addr, a.addr, b.addr, &c.shape, (c.default_stride ? NULL : &c.stride), (a.default_stride ? NULL : &a.stride), (b.default_stride ? NULL : &b.stride), DT_FP16);
#ifndef USING_CMODEL
      tpu_parallel_end();
#endif
      __tilelang_tpu_tensor_info c_1 = {.shape = {1, 128, 1, 1024} , .stride = c.stride, .addr = c.addr + ((0) * c.stride.c+(0) * c.stride.w ) * 2, .default_stride = c.default_stride};
      __tilelang_tpu_tensor_info output = {.shape = {1, 128, 1, 1024} , .stride = {1048576, 1024, 1024, 1} , .addr = v6.addr + (((tile_pipeline * 128)) * 1024+(0) * 1 ) * 2, .default_stride = false};
      tpu_gdma_cpy_L2S(output.addr, c_1.addr, &output.shape, (output.default_stride ? NULL : &output.stride), (c_1.default_stride ? NULL : &c_1.stride), DT_FP16);
    }
    if (0 < (tile_pipeline % 2)) {
#ifndef USING_CMODEL
      tpu_parallel_start();
#endif
      __tilelang_tpu_tensor_info lhs_2 = {.shape = {1, 128, 1, 1024} , .stride = {1048576, 1024, 1024, 1} , .addr = v4.addr + ((((tile_pipeline * 128) + 128)) * 1024+(0) * 1 ) * 2, .default_stride = false};
      __tilelang_tpu_tensor_info a_2 = {.shape = {1, 128, 1, 1024} , .stride = a.stride, .addr = a.addr + ((0) * a.stride.c+(0) * a.stride.w ) * 2, .default_stride = a.default_stride};
      tpu_gdma_cpy_S2L(a_2.addr, lhs_2.addr, &a_2.shape, (a_2.default_stride ? NULL : &a_2.stride), (lhs_2.default_stride ? NULL : &lhs_2.stride), DT_FP16);
      __tilelang_tpu_tensor_info rhs_2 = {.shape = {1, 128, 1, 1024} , .stride = {1048576, 1024, 1024, 1} , .addr = v5.addr + ((((tile_pipeline * 128) + 128)) * 1024+(0) * 1 ) * 2, .default_stride = false};
      __tilelang_tpu_tensor_info b_2 = {.shape = {1, 128, 1, 1024} , .stride = b.stride, .addr = b.addr + ((0) * b.stride.c+(0) * b.stride.w ) * 2, .default_stride = b.default_stride};
      tpu_gdma_cpy_S2L(b_2.addr, rhs_2.addr, &b_2.shape, (b_2.default_stride ? NULL : &b_2.stride), (rhs_2.default_stride ? NULL : &rhs_2.stride), DT_FP16);
      tpu_bdc_fp_sub(c.addr, a_pipeline_v1.addr, b_pipeline_v1.addr, &c.shape, (c.default_stride ? NULL : &c.stride), (a_pipeline_v1.default_stride ? NULL : &a_pipeline_v1.stride), (b_pipeline_v1.default_stride ? NULL : &b_pipeline_v1.stride), DT_FP16);
#ifndef USING_CMODEL
      tpu_parallel_end();
#endif
      __tilelang_tpu_tensor_info c_2 = {.shape = {1, 128, 1, 1024} , .stride = c.stride, .addr = c.addr + ((0) * c.stride.c+(0) * c.stride.w ) * 2, .default_stride = c.default_stride};
      __tilelang_tpu_tensor_info output_1 = {.shape = {1, 128, 1, 1024} , .stride = {1048576, 1024, 1024, 1} , .addr = v6.addr + (((tile_pipeline * 128)) * 1024+(0) * 1 ) * 2, .default_stride = false};
      tpu_gdma_cpy_L2S(output_1.addr, c_2.addr, &output_1.shape, (output_1.default_stride ? NULL : &output_1.stride), (c_2.default_stride ? NULL : &c_2.stride), DT_FP16);
    }
  }
  tpu_bdc_fp_sub(c.addr, a_pipeline_v1.addr, b_pipeline_v1.addr, &c.shape, (c.default_stride ? NULL : &c.stride), (a_pipeline_v1.default_stride ? NULL : &a_pipeline_v1.stride), (b_pipeline_v1.default_stride ? NULL : &b_pipeline_v1.stride), DT_FP16);
  __tilelang_tpu_tensor_info c_3 = {.shape = {1, 128, 1, 1024} , .stride = c.stride, .addr = c.addr + ((0) * c.stride.c+(0) * c.stride.w ) * 2, .default_stride = c.default_stride};
  __tilelang_tpu_tensor_info output_2 = {.shape = {1, 128, 1, 1024} , .stride = {1048576, 1024, 1024, 1} , .addr = v6.addr + ((896) * 1024+(0) * 1 ) * 2, .default_stride = false};
  tpu_gdma_cpy_L2S(output_2.addr, c_3.addr, &output_2.shape, (output_2.default_stride ? NULL : &output_2.stride), (c_3.default_stride ? NULL : &c_3.stride), DT_FP16);
}

typedef struct {
  global_addr_t v1;
  global_addr_t v2;
  global_addr_t v3;
} tpu_kernel_api_main_inner_args_t;
int main_kernel(const void * args) {
  tpu_kernel_api_main_inner_args_t *api = (tpu_kernel_api_main_inner_args_t*)args;
  tpu_initialize();
  elementwise_tiled(api->v1,
    api->v2,
    api->v3);
  tpu_poll();
  return 0;
}
TPUKERNEL_FUNC_REGISTER(main_kernel)

